 <?php endforeach;if(!$visible):?><tr><td colspan="14" class="lb-empty">Không có tiết nào thuộc phạm vi tài khoản trong phạm vi đã chọn. Kiểm tra TKB và phần ghép tên giáo viên.</td></tr><?php endif;?></tbody></table></div></section><script>(function(){function syncPpct(input,force){var formId=input.getAttribute('form'),lesson=document.querySelector('[form="'+formId+'"][name="lesson_title"]'),titles={};try{titles=JSON.parse(input.dataset.titles||'{}')}catch(e){}if(!lesson)return;var title=titles[String(Number(input.value||0))]||'',previous=lesson.dataset.autoTitle||'';if(title){if(force||!lesson.value.trim()||lesson.value===previous){lesson.value=title;lesson.dataset.autoTitle=title;lesson.classList.remove('is-invalid');lesson.title='Tên bài được lấy tự động từ PPCT'}}else if(previous&&lesson.value===previous){lesson.value='';lesson.dataset.autoTitle='';lesson.title='Không tìm thấy tên bài tương ứng trong PPCT'}}document.querySelectorAll('.lb-ppct').forEach(function(input){input.addEventListener('input',function(){syncPpct(input,false)});input.addEventListener('change',function(){syncPpct(input,false)});syncPpct(input,true)})})()</script><script>(function(){document.querySelectorAll('.lb-record-form').forEach(function(form){form.addEventListener('submit',function(event){document.querySelectorAll('[form="'+form.id+'"]').forEach(function(x){x.classList.remove('is-invalid')});var get=function(name){return document.querySelector('[form="'+form.id+'"][name="'+name+'"]')},status=get('status'),missing=[];if(!status||status.value==='pending'){missing.push('trạng thái hoàn thành');if(status)status.classList.add('is-invalid')}if(status&&['taught','substitute','makeup','online'].includes(status.value)){[['actual_teacher','giáo viên thực tế'],['ppct_period','tiết PPCT'],['lesson_title','đầu bài/nội dung'],['rating','xếp loại']].forEach(function(pair){var input=get(pair[0]),empty=!input||!String(input.value||'').trim()||(pair[0]==='ppct_period'&&Number(input.value)<1);if(empty){missing.push(pair[1]);if(input)input.classList.add('is-invalid')}});var ppct=get('ppct_period'),period=Number(ppct&&ppct.value||0),used=[];try{used=JSON.parse(ppct&&ppct.dataset.used||'[]').map(Number)}catch(e){}if(period>0&&used.includes(period)){event.preventDefault();ppct.classList.add('is-invalid');alert((form.dataset.label||'Tiết học')+': tiết PPCT '+period+' đã được nhập trước đó.');return}if(period>1&&!used.includes(period-1)){event.preventDefault();ppct.classList.add('is-invalid');alert((form.dataset.label||'Tiết học')+': chưa có tiết PPCT '+(period-1)+', không thể nhập tiết '+period+'.');return}}if(missing.length){event.preventDefault();alert((form.dataset.label||'Tiết học')+' chưa thể ký. Còn thiếu: '+missing.join(', ')+'.')}})})})()</script>
