 <section class="lb-card"><div class="d-flex flex-wrap justify-content-between gap-2"><div><h2 class="h5 mb-1">Đưa PPCT lên từ Excel</h2><p class="lb-note mb-0"><?=lb_is_admin()?'Quản trị có thể nhập hoặc cập nhật dữ liệu.':'Mỗi lần tải một tệp cho đúng một Môn–Khối trong PCCM. Giáo viên không được sửa hoặc ghi đè PPCT đã có.'?></p></div><a class="btn btn-outline-success align-self-start" href="<?=BASE_URL?>sodaubai_ppct_template.php"><i class="bi bi-download"></i> Tải mẫu Excel</a></div><form method="post" enctype="multipart/form-data" class="row g-2 align-items-end mt-2" id="lbCurriculumImport"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="import_curriculum"><?php if(!lb_is_admin()):?><div class="col-lg-4"><label class="form-label fw-bold">Môn–Khối được phân công</label><select class="form-select" id="lbCurriculumScope" required><option value="">Chọn Môn–Khối trước khi tải</option><?php foreach($curriculumScopes as$i=>$s):?><option value="<?=$i?>" data-subject="<?=e($s['subject'])?>" data-grade="<?=e($s['grade'])?>"><?=e($s['subject'])?> – Khối <?=e($s['grade'])?><?=lb_curriculum_scope_exists((string)$s['subject'],(string)$s['grade'])?' (đã có PPCT)':''?></option><?php endforeach;?></select><input type="hidden" name="target_subject" id="lbCurriculumSubject"><input type="hidden" name="target_grade" id="lbCurriculumGrade"><div class="form-text">Tệp phải chỉ chứa dữ liệu của đúng Môn–Khối đã chọn.</div></div><?php endif;?><div class="<?=lb_is_admin()?'col-lg-9':'col-lg-5'?>"><label class="form-label fw-bold">Tệp PPCT (.xlsx)</label><input class="form-control" type="file" name="curriculum_file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required></div><div class="col-lg-3"><button class="btn btn-success w-100"><i class="bi bi-file-earmark-arrow-up"></i> Kiểm tra và tải lên</button></div></form><?php if(!lb_is_admin()):?><script>(function(){const form=document.getElementById('lbCurriculumImport'),scope=document.getElementById('lbCurriculumScope'),subject=document.getElementById('lbCurriculumSubject'),grade=document.getElementById('lbCurriculumGrade');if(!form||!scope)return;const sync=()=>{const option=scope.options[scope.selectedIndex];subject.value=option?.dataset.subject||'';grade.value=option?.dataset.grade||''};scope.addEventListener('change',sync);form.addEventListener('submit',sync);sync()})()</script><?php endif;?></section>
 <?php if(lb_is_admin()):?><section class="lb-card"><h2 class="h5">Quản trị PPCT</h2><p class="lb-note">Chỉ quản trị được sửa từng dòng hoặc xóa toàn bộ PPCT của một Môn–Khối. Sau khi xóa, giáo viên có PCCM phù hợp có thể tải lại.</p><form method="post" class="row g-2 align-items-end mb-3"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="delete_curriculum_scope"><?php $scopeOptions=[];foreach(lb_curriculum()as$r){$sk=lb_norm((string)($r['subject']??'')).'|'.preg_replace('/\D+/','',(string)($r['grade']??''));$scopeOptions[$sk]=['subject'=>(string)($r['subject']??''),'grade'=>preg_replace('/\D+/','',(string)($r['grade']??''))];}?><div class="col-lg-9"><label class="form-label fw-bold">PPCT cần xóa để tải lại</label><select class="form-select" id="lbDeleteScope" required><option value="">Chọn Môn – Khối</option><?php foreach($scopeOptions as$s):?><option value="<?=e($s['subject'].'|'.$s['grade'])?>"><?=e($s['subject'])?> – Khối <?=e($s['grade'])?></option><?php endforeach;?></select><input type="hidden" name="subject" id="lbDeleteSubject"><input type="hidden" name="grade" id="lbDeleteGrade"></div><div class="col-lg-3"><button class="btn btn-danger w-100" onclick="const v=document.getElementById('lbDeleteScope').value.split('|');if(v.length<2)return false;document.getElementById('lbDeleteGrade').value=v.pop();document.getElementById('lbDeleteSubject').value=v.join('|');return confirm('Xóa toàn bộ PPCT Môn–Khối đã chọn?');"><i class="bi bi-trash"></i> Xóa để tải lại</button></div></form><h3 class="h6">Nhập hoặc sửa một dòng PPCT</h3><form method="post" class="row g-2 align-items-end"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="save_curriculum"><div class="col-md-3"><label class="form-label">Môn</label><input class="form-control" name="subject" required></div><div class="col-md-2"><label class="form-label">Khối</label><input class="form-control" name="grade" required></div><div class="col-md-2"><label class="form-label">Tiết PPCT</label><input class="form-control" type="number" min="1" name="period" required></div><div class="col-md-4"><label class="form-label">Tên bài / nội dung</label><input class="form-control" name="title" required></div><div class="col-md-1"><button class="btn btn-primary">Lưu</button></div></form></section><?php endif;?><section class="lb-card"><div class="d-flex justify-content-between"><h2 class="h5">Danh mục PPCT<?=lb_is_admin()?'':' trong phạm vi được giao'?></h2><span class="badge text-bg-primary"><?=count($curriculumRows)?> dòng</span></div><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Môn</th><th>Khối</th><th>Tiết</th><th>Tên bài</th><th>Ghi chú</th><th>Người cập nhật</th></tr></thead><tbody><?php $cur=$curriculumRows;usort($cur,fn($a,$b)=>strcmp(($a['subject'].'|'.$a['grade'].'|'.sprintf('%04d',$a['period'])),($b['subject'].'|'.$b['grade'].'|'.sprintf('%04d',$b['period']))));foreach($cur as$r):?><tr><td><?=e($r['subject'])?></td><td><?=e($r['grade'])?></td><td class="text-center"><?=e($r['period'])?></td><td><?=e($r['title'])?></td><td><?=e($r['note']??'')?></td><td><?=e($r['updated_by']??$r['created_by']??'')?></td></tr><?php endforeach;?></tbody></table></div></section>
 <?php elseif($tab==='signature'):?>
 <section class="lb-card"><h2 class="h5">Ảnh chữ ký giáo viên</h2><p>Ảnh được trình duyệt tự động cắt khoảng trắng, giữ đúng tỷ lệ và đặt trong khung PNG trong suốt 480 × 160 px; không phụ thuộc thư viện xử lý ảnh của máy chủ. Giáo viên phải có ảnh chữ ký trước khi bấm Ký trong Ghi sổ.</p><?php if($sig=lb_signature_meta()):?><div class="alert alert-success">Đã có chữ ký phiên bản <?=e($sig['version'])?>, tạo lúc <?=e($sig['created_at'])?>.</div><?php endif;?><form method="post" enctype="multipart/form-data" id="lbSignatureForm"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="upload_signature"><div class="input-group"><input class="form-control" type="file" name="signature" id="lbSignatureFile" accept="image/png,image/jpeg" required><button class="btn btn-primary" id="lbSignatureButton"><i class="bi bi-crop"></i> Chuẩn hóa và lưu</button></div><div class="form-text" id="lbSignatureStatus">Chọn ảnh PNG hoặc JPG có nét chữ ký rõ ràng.</div></form></section><script>(function(){const form=document.getElementById('lbSignatureForm'),input=document.getElementById('lbSignatureFile'),status=document.getElementById('lbSignatureStatus'),button=document.getElementById('lbSignatureButton');if(!form||!input)return;form.addEventListener('submit',async function(ev){if(form.dataset.ready==='1')return;ev.preventDefault();const file=input.files&&input.files[0];if(!file)return;button.disabled=true;status.textContent='Đang cắt và chuẩn hóa ảnh chữ ký…';try{const bitmap=await createImageBitmap(file),src=document.createElement('canvas');src.width=bitmap.width;src.height=bitmap.height;const ctx=src.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0);const data=ctx.getImageData(0,0,src.width,src.height),px=data.data;let minX=src.width,minY=src.height,maxX=-1,maxY=-1;for(let y=0;y<src.height;y++)for(let x=0;x<src.width;x++){const i=(y*src.width+x)*4;if(px[i+3]>15&&Math.min(px[i],px[i+1],px[i+2])<238){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y)}}if(maxX<minX)throw new Error('Không nhận thấy nét chữ ký trong ảnh.');const out=document.createElement('canvas');out.width=480;out.height=160;const o=out.getContext('2d'),cw=maxX-minX+1,ch=maxY-minY+1,scale=Math.min(440/cw,120/ch),nw=Math.round(cw*scale),nh=Math.round(ch*scale);o.clearRect(0,0,480,160);o.drawImage(src,minX,minY,cw,ch,Math.round((480-nw)/2),Math.round((160-nh)/2),nw,nh);const blob=await new Promise(resolve=>out.toBlob(resolve,'image/png',1));if(!blob)throw new Error('Không tạo được ảnh PNG.');const transfer=new DataTransfer();transfer.items.add(new File([blob],'chu-ky-da-chuan-hoa.png',{type:'image/png'}));input.files=transfer.files;form.dataset.ready='1';status.textContent='Đã chuẩn hóa 480 × 160 px, đang lưu…';form.submit()}catch(err){button.disabled=false;status.textContent=err.message||'Không xử lý được ảnh chữ ký.'}})})();</script>
