 <section class="lb-card"><div class="d-flex justify-content-between gap-2 flex-wrap"><div><h2 class="h5 mb-1">Khóa sổ theo lịch chung</h2><p class="lb-note mb-0">Chọn một hoặc nhiều tuần rồi khóa/mở toàn trường, một khối hoặc một lớp trong một lần. Đây là cơ chế khóa duy nhất của Sổ đầu bài.</p></div><div><button type="button" class="btn btn-sm btn-outline-primary" data-week-pick="all">Chọn tất cả</button> <button type="button" class="btn btn-sm btn-outline-secondary" data-week-pick="none">Bỏ chọn</button></div></div><form method="post" id="bulkLockForm" class="mt-3" onsubmit="return confirm('Xác nhận thay đổi trạng thái khóa sổ cho toàn bộ phạm vi và các tuần đã chọn?')"><input type="hidden" name="csrf" value="<?=$csrf?>"><div class="row g-3"><div class="col-lg-7"><label class="form-label fw-bold">Các tuần áp dụng</label><div class="border rounded p-2 d-flex flex-wrap gap-2" style="max-height:190px;overflow:auto"><?php foreach($bulkWeeks as$bw):?><label class="border rounded px-2 py-1"><input class="form-check-input bulk-week" type="checkbox" name="week_keys[]" value="<?=e($bw['key'])?>" <?=$bw['key']===$weekKey?'checked':''?>> <?=e($bw['label'])?> <small class="text-muted"><?=date('d/m',strtotime($bw['start']))?>–<?=date('d/m',strtotime($bw['end']))?></small></label><?php endforeach;?></div></div><div class="col-lg-5"><label class="form-label fw-bold">Phạm vi</label><select class="form-select mb-2" name="lock_scope" id="bulkLockScope"><option value="school">Toàn trường</option><option value="grade">Theo khối</option><option value="class">Theo lớp</option></select><select class="form-select mb-2 d-none" name="lock_grade" id="bulkLockGrade"><option value="">Chọn khối</option><?php foreach($bulkGrades as$bg):?><option value="<?=e($bg)?>">Khối <?=e($bg)?></option><?php endforeach;?></select><select class="form-select mb-2 d-none" name="lock_class" id="bulkLockClass"><option value="">Chọn lớp</option><?php foreach($bulkClasses as$bc):?><option value="<?=e($bc)?>"><?=e($bc)?></option><?php endforeach;?></select><input class="form-control" name="reason" required placeholder="Lý do khóa hoặc mở khóa"></div></div><div class="mt-3"><button class="btn btn-danger" name="action" value="bulk_lock"><i class="bi bi-lock"></i> Khóa phạm vi đã chọn</button> <button class="btn btn-success" name="action" value="bulk_unlock"><i class="bi bi-unlock"></i> Mở khóa phạm vi đã chọn</button></div></form></section>
